mapper.select:
SELECT COUNT(DISTINCT issue_group_id)
FROM tb_ai_log_error_event
WHERE analysis_task_id = #{analysisTaskId}

SELECT COALESCE(SUM(occurrence_count), 0)
FROM tb_ai_log_error_event
WHERE analysis_task_id = #{analysisTaskId}

SELECT event.*
FROM tb_ai_log_error_event event
JOIN tb_ai_log_analysis_task analysis ON analysis.id = event.analysis_task_id
WHERE event.issue_group_id = #{issueGroupId}
  AND event.log_date = #{logDate}
  AND analysis.status = 'SUCCESS'
  AND event.expected = 0
  AND event.ai_required = 1

LIMIT #{limit}
